require_once __DIR__ . '/../../app/config/init.php'; require_login(); require_role('Administrator','Time Keeper'); require_once __DIR__ . '/dtr_helpers.php';
$page_title='DTR Schedule Settings';$db=db();$errors=[];$flash=get_flash();$schedule=$db?dtr_load_schedule($db):dtr_default_schedule();
if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_verify()){$errors[]='Invalid CSRF token.';}else{$schedule=['am_login'=>trim($_POST['am_login']??''),'am_logout'=>trim($_POST['am_logout']??''),'pm_login'=>trim($_POST['pm_login']??''),'pm_logout'=>trim($_POST['pm_logout']??''),'grace_minutes'=>(int)($_POST['grace_minutes']??0)];foreach(['am_login','am_logout','pm_login','pm_logout'] as $f){if(!preg_match('/^\d{2}:\d{2}$/',$schedule[$f]))$errors[]='All schedule times are required.';}if($schedule['grace_minutes']<0)$errors[]='Grace minutes cannot be negative.';if(!$errors&&$db){$user=current_user_id();$stmt=$db->prepare('UPDATE dtr_schedule SET am_login=?,am_logout=?,pm_login=?,pm_logout=?,grace_minutes=?,updated_by=? WHERE id=1');$stmt->bind_param('ssssii',$schedule['am_login'],$schedule['am_logout'],$schedule['pm_login'],$schedule['pm_logout'],$schedule['grace_minutes'],$user);if($stmt->execute()){set_flash('success','DTR schedule updated.');redirect('modules/dtr/settings.php');}$errors[]='Unable to update schedule.';$stmt->close();}}}
require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';require_once __DIR__.'/../../includes/topbar.php';?><section class="row page-section"><div class="col-lg-7"><div class="card"><div class="card-body p-4"><div class="workspace-header mb-3"><div class="workspace-header-copy"><p class="page-kicker mb-1">OJT / DTR</p><h5 class="page-title mb-1">Global DTR Schedule</h5><p class="text-muted mb-0">Arrival scans within the grace period are credited to the scheduled login time. Raw scans remain unchanged.</p></div></div><?php if($flash):?><div class="alert alert-success"><?php echo h($flash['message']);?></div><?php endif;?><?php foreach($errors as $e):?><div class="alert alert-danger"><?php echo h($e);?></div><?php endforeach;?><form method="post" class="row g-3"><input type="hidden" name="_csrf" value="<?php echo h(csrf_token());?>"><div class="col-md-6"><label class="form-label">AM Login</label><input class="form-control" type="time" name="am_login" value="<?php echo h(substr($schedule['am_login'],0,5));?>" required></div><div class="col-md-6"><label class="form-label">AM Logout</label><input class="form-control" type="time" name="am_logout" value="<?php echo h(substr($schedule['am_logout'],0,5));?>" required></div><div class="col-md-6"><label class="form-label">PM Login</label><input class="form-control" type="time" name="pm_login" value="<?php echo h(substr($schedule['pm_login'],0,5));?>" required></div><div class="col-md-6"><label class="form-label">PM Logout</label><input class="form-control" type="time" name="pm_logout" value="<?php echo h(substr($schedule['pm_logout'],0,5));?>" required></div><div class="col-md-6"><label class="form-label">Grace Minutes</label><input class="form-control" type="number" name="grace_minutes" min="0" value="<?php echo (int)$schedule['grace_minutes'];?>" required></div><div class="col-12"><button class="btn btn-primary">Save Schedule</button></div></form></div></div></div></section><?php 